window.MG_LAZY_DATA["data/lazy/courses/a079-0cf0f69d6d765f36.json"]={sha256:"0cf0f69d6d765f367a920e275665ea76ca3a3ab68150e3d64769dd713f4cb6ac",value:{"id":"a079","title":"雪崩光二極體製作","titleEn":"Avalanche photodiode fabrication","category":"semiconductor","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":550,"languageCoverage":["zh-TW","en"],"sourceIds":["v8-c-apd","v8-c-sipm","v8-c-ham-place","v8-c-ham-history","v3-media-80679a241086"],"simulationOnly":true,"summary":"從吸收與倍增、暗電流來源到偵測系統：以 12 項工程決策、24 個模型與診斷工作包建立證據。","summaryEn":"From Absorption and multiplication and Dark-current sources to Detection system: build evidence through twelve engineering decisions and twenty-four modeling/diagnostic work packages.","scope":"公開原理的教學拆解：12 個技術主題各有模型／分析及故障／驗證兩步，共四階段 24 步。不是 24 道實際製造配方，也不是任何廠商量產流程。數值由學員自訂並標示為假設；涉及材料加工、高壓、雷射或化學品的活動僅做圖上與資料分析，不由網頁授權實機操作。","scopeEn":"A public-principles educational decomposition: twelve technical topics each have a model/analysis step and a diagnosis/verification step, organized as four stages and twenty-four work packages. These are not twenty-four fabrication recipes or a manufacturer flow. Learner-selected numbers are hypothetical; materials processing, high voltage, lasers and chemicals are studied through diagrams/data, not authorized physical operation.","diagram":{"type":"wafer","labels":["吸收與倍增","倍增雜訊","頻寬限制","接觸與封裝"],"labelsEn":["Absorption and multiplication","Multiplication noise","Bandwidth limits","Contacts and package"],"original":true,"notToScale":true},"stages":[{"id":"a079-stage01","order":1,"title":"吸收與倍增 → 場形塑","titleEn":"Absorption and multiplication to Field shaping","description":"把「吸收與倍增」「線性模式」「場形塑」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Absorption and multiplication, Linear mode, Field shaping.","steps":[{"id":"a079-v8-01","order":1,"sequence":1,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":[],"title":"吸收與倍增：建立模型","titleEn":"Absorption and multiplication: construct and analyze","objective":"用可檢查的成果說明「光吸收與雪崩倍增可有不同空間要求」。","objectiveEn":"Demonstrate the following with inspectable work: Absorption and avalanche multiplication have different spatial requirements.","instruction":"畫吸收區與高電場倍增區，追蹤一對光生載子。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw absorption/multiplication regions and track a photogenerated pair. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"光吸收與雪崩倍增可有不同空間要求；電子和電洞游離率可能不同。","observationEn":"Absorption and avalanche multiplication have different spatial requirements; Electron and hole ionization rates can differ.","failure":"若採用「把整個元件都畫成相同高場」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Drawing uniform high field throughout the device\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「吸收與倍增」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：光吸收與雪崩倍增可有不同空間要求。","checkEn":"Submit the Absorption and multiplication diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Absorption and avalanche multiplication have different spatial requirements.","knowledge":[{"id":"a079-v8-01-k1","title":"吸收與倍增／物理與模型","titleEn":"Absorption and multiplication / Physics and model","text":"機制：光吸收與雪崩倍增可有不同空間要求。","textEn":"Mechanism: Absorption and avalanche multiplication have different spatial requirements."},{"id":"a079-v8-01-k2","title":"吸收與倍增／驗證與限制","titleEn":"Absorption and multiplication / Verification and limits","text":"模型邊界：不可由目前成果直接推出「把整個元件都畫成相同高場」。","textEn":"Model boundary: the current result does not establish the following claim: Drawing uniform high field throughout the device."}],"quiz":{"question":"關於「吸收與倍增」，哪項推論有物理依據？","questionEn":"For Absorption and multiplication, which inference has a physical basis?","options":["光吸收與雪崩倍增可有不同空間要求","把整個元件都畫成相同高場","APD 有增益便必須工作在崩潰以上"],"optionsEn":["Absorption and avalanche multiplication have different spatial requirements","Drawing uniform high field throughout the device","Assuming gain requires above-breakdown operation"],"answer":0,"explanation":"光吸收與雪崩倍增可有不同空間要求；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Absorption and avalanche multiplication have different spatial requirements. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-02","order":2,"sequence":2,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-01"],"title":"吸收與倍增：故障判讀與驗證","titleEn":"Absorption and multiplication: diagnose and verify","objective":"以新增對照檢查「把整個元件都畫成相同高場」這項錯誤主張。","objectiveEn":"Test the faulty claim: Drawing uniform high field throughout the device.","instruction":"接續前一步「吸收與倍增」成果，先指出錯誤主張「把整個元件都畫成相同高場」漏掉哪個條件。新增診斷原理：電子和電洞游離率可能不同。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Absorption and multiplication artifact. Identify the missing condition in the faulty claim \"Drawing uniform high field throughout the device\". Introduce this diagnostic principle: Electron and hole ionization rates can differ. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"光吸收與雪崩倍增可有不同空間要求；電子和電洞游離率可能不同。","observationEn":"Absorption and avalanche multiplication have different spatial requirements; Electron and hole ionization rates can differ.","failure":"若採用「把整個元件都畫成相同高場」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Drawing uniform high field throughout the device\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「吸收與倍增」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「電子和電洞游離率可能不同」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Absorption and multiplication, its observable and one remaining uncertainty. Explain how \"Electron and hole ionization rates can differ\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-02-k1","title":"吸收與倍增／物理與模型","titleEn":"Absorption and multiplication / Physics and model","text":"診斷機制：電子和電洞游離率可能不同。","textEn":"Diagnostic mechanism: Electron and hole ionization rates can differ."},{"id":"a079-v8-02-k2","title":"吸收與倍增／驗證與限制","titleEn":"Absorption and multiplication / Verification and limits","text":"可證偽性：「把整個元件都畫成相同高場」與「光吸收與雪崩倍增可有不同空間要求」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Drawing uniform high field throughout the device\" is not equivalent to \"Absorption and avalanche multiplication have different spatial requirements\"; the control must expose their difference."}],"quiz":{"question":"檢查「吸收與倍增」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Absorption and multiplication?","options":["APD 有增益便必須工作在崩潰以上","電子和電洞游離率可能不同","把整個元件都畫成相同高場"],"optionsEn":["Assuming gain requires above-breakdown operation","Electron and hole ionization rates can differ","Drawing uniform high field throughout the device"],"answer":1,"explanation":"電子和電洞游離率可能不同；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Electron and hole ionization rates can differ. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-03","order":3,"sequence":3,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-02"],"title":"線性模式：建立模型","titleEn":"Linear mode: construct and analyze","objective":"用可檢查的成果說明「線性 APD 增益與 Geiger 觸發不同」。","objectiveEn":"Demonstrate the following with inspectable work: Linear APD gain differs from Geiger triggering.","instruction":"在增益對偏壓曲線標出崩潰前工作範圍。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Mark the pre-breakdown operating region on a gain-bias plot. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"線性 APD 增益與 Geiger 觸發不同；串聯電阻會改變接面實際偏壓。","observationEn":"Linear APD gain differs from Geiger triggering; Series resistance changes actual junction bias.","failure":"若採用「APD 有增益便必須工作在崩潰以上」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming gain requires above-breakdown operation\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「線性模式」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：線性 APD 增益與 Geiger 觸發不同。","checkEn":"Submit the Linear mode diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Linear APD gain differs from Geiger triggering.","knowledge":[{"id":"a079-v8-03-k1","title":"線性模式／物理與模型","titleEn":"Linear mode / Physics and model","text":"機制：線性 APD 增益與 Geiger 觸發不同。","textEn":"Mechanism: Linear APD gain differs from Geiger triggering."},{"id":"a079-v8-03-k2","title":"線性模式／驗證與限制","titleEn":"Linear mode / Verification and limits","text":"模型邊界：不可由目前成果直接推出「APD 有增益便必須工作在崩潰以上」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming gain requires above-breakdown operation."}],"quiz":{"question":"關於「線性模式」，哪項推論有物理依據？","questionEn":"For Linear mode, which inference has a physical basis?","options":["APD 有增益便必須工作在崩潰以上","只用平均接面電場判斷崩潰位置","線性 APD 增益與 Geiger 觸發不同"],"optionsEn":["Assuming gain requires above-breakdown operation","Locating breakdown from mean junction field alone","Linear APD gain differs from Geiger triggering"],"answer":2,"explanation":"線性 APD 增益與 Geiger 觸發不同；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Linear APD gain differs from Geiger triggering. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-04","order":4,"sequence":4,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-03"],"title":"線性模式：故障判讀與驗證","titleEn":"Linear mode: diagnose and verify","objective":"以新增對照檢查「APD 有增益便必須工作在崩潰以上」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming gain requires above-breakdown operation.","instruction":"接續前一步「線性模式」成果，先指出錯誤主張「APD 有增益便必須工作在崩潰以上」漏掉哪個條件。新增診斷原理：串聯電阻會改變接面實際偏壓。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Linear mode artifact. Identify the missing condition in the faulty claim \"Assuming gain requires above-breakdown operation\". Introduce this diagnostic principle: Series resistance changes actual junction bias. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"線性 APD 增益與 Geiger 觸發不同；串聯電阻會改變接面實際偏壓。","observationEn":"Linear APD gain differs from Geiger triggering; Series resistance changes actual junction bias.","failure":"若採用「APD 有增益便必須工作在崩潰以上」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming gain requires above-breakdown operation\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「線性模式」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「串聯電阻會改變接面實際偏壓」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Linear mode, its observable and one remaining uncertainty. Explain how \"Series resistance changes actual junction bias\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-04-k1","title":"線性模式／物理與模型","titleEn":"Linear mode / Physics and model","text":"診斷機制：串聯電阻會改變接面實際偏壓。","textEn":"Diagnostic mechanism: Series resistance changes actual junction bias."},{"id":"a079-v8-04-k2","title":"線性模式／驗證與限制","titleEn":"Linear mode / Verification and limits","text":"可證偽性：「APD 有增益便必須工作在崩潰以上」與「線性 APD 增益與 Geiger 觸發不同」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming gain requires above-breakdown operation\" is not equivalent to \"Linear APD gain differs from Geiger triggering\"; the control must expose their difference."}],"quiz":{"question":"檢查「線性模式」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Linear mode?","options":["串聯電阻會改變接面實際偏壓","APD 有增益便必須工作在崩潰以上","只用平均接面電場判斷崩潰位置"],"optionsEn":["Series resistance changes actual junction bias","Assuming gain requires above-breakdown operation","Locating breakdown from mean junction field alone"],"answer":0,"explanation":"串聯電阻會改變接面實際偏壓；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Series resistance changes actual junction bias. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-05","order":5,"sequence":5,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-04"],"title":"場形塑：建立模型","titleEn":"Field shaping: construct and analyze","objective":"用可檢查的成果說明「邊緣可能先於中央發生崩潰」。","objectiveEn":"Demonstrate the following with inspectable work: Edges can break down before the central region.","instruction":"畫平面接面及邊緣曲率，說明護環如何改變局部場。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw planar and curved junction edges and explain guard-ring field shaping. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"邊緣可能先於中央發生崩潰；表面電荷也會扭曲邊緣電場。","observationEn":"Edges can break down before the central region; Surface charge distorts edge fields.","failure":"若採用「只用平均接面電場判斷崩潰位置」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Locating breakdown from mean junction field alone\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「場形塑」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：邊緣可能先於中央發生崩潰。","checkEn":"Submit the Field shaping diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Edges can break down before the central region.","knowledge":[{"id":"a079-v8-05-k1","title":"場形塑／物理與模型","titleEn":"Field shaping / Physics and model","text":"機制：邊緣可能先於中央發生崩潰。","textEn":"Mechanism: Edges can break down before the central region."},{"id":"a079-v8-05-k2","title":"場形塑／驗證與限制","titleEn":"Field shaping / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只用平均接面電場判斷崩潰位置」。","textEn":"Model boundary: the current result does not establish the following claim: Locating breakdown from mean junction field alone."}],"quiz":{"question":"關於「場形塑」，哪項推論有物理依據？","questionEn":"For Field shaping, which inference has a physical basis?","options":["把內部增益當成完全無雜訊放大","邊緣可能先於中央發生崩潰","只用平均接面電場判斷崩潰位置"],"optionsEn":["Treating internal gain as noiseless amplification","Edges can break down before the central region","Locating breakdown from mean junction field alone"],"answer":1,"explanation":"邊緣可能先於中央發生崩潰；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Edges can break down before the central region. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-06","order":6,"sequence":6,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-05"],"title":"場形塑：故障判讀與驗證","titleEn":"Field shaping: diagnose and verify","objective":"以新增對照檢查「只用平均接面電場判斷崩潰位置」這項錯誤主張。","objectiveEn":"Test the faulty claim: Locating breakdown from mean junction field alone.","instruction":"接續前一步「場形塑」成果，先指出錯誤主張「只用平均接面電場判斷崩潰位置」漏掉哪個條件。新增診斷原理：表面電荷也會扭曲邊緣電場。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Field shaping artifact. Identify the missing condition in the faulty claim \"Locating breakdown from mean junction field alone\". Introduce this diagnostic principle: Surface charge distorts edge fields. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"邊緣可能先於中央發生崩潰；表面電荷也會扭曲邊緣電場。","observationEn":"Edges can break down before the central region; Surface charge distorts edge fields.","failure":"若採用「只用平均接面電場判斷崩潰位置」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Locating breakdown from mean junction field alone\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「場形塑」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「表面電荷也會扭曲邊緣電場」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Field shaping, its observable and one remaining uncertainty. Explain how \"Surface charge distorts edge fields\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-06-k1","title":"場形塑／物理與模型","titleEn":"Field shaping / Physics and model","text":"診斷機制：表面電荷也會扭曲邊緣電場。","textEn":"Diagnostic mechanism: Surface charge distorts edge fields."},{"id":"a079-v8-06-k2","title":"場形塑／驗證與限制","titleEn":"Field shaping / Verification and limits","text":"可證偽性：「只用平均接面電場判斷崩潰位置」與「邊緣可能先於中央發生崩潰」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Locating breakdown from mean junction field alone\" is not equivalent to \"Edges can break down before the central region\"; the control must expose their difference."}],"quiz":{"question":"檢查「場形塑」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Field shaping?","options":["只用平均接面電場判斷崩潰位置","把內部增益當成完全無雜訊放大","表面電荷也會扭曲邊緣電場"],"optionsEn":["Locating breakdown from mean junction field alone","Treating internal gain as noiseless amplification","Surface charge distorts edge fields"],"answer":2,"explanation":"表面電荷也會扭曲邊緣電場；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Surface charge distorts edge fields. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a079-stage02","order":2,"title":"倍增雜訊 → 溫度補償","titleEn":"Multiplication noise to Temperature compensation","description":"把「倍增雜訊」「暗電流來源」「溫度補償」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Multiplication noise, Dark-current sources, Temperature compensation.","steps":[{"id":"a079-v8-07","order":1,"sequence":7,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-06"],"title":"倍增雜訊：建立模型","titleEn":"Multiplication noise: construct and analyze","objective":"用可檢查的成果說明「雪崩的隨機性會增加訊號變異」。","objectiveEn":"Demonstrate the following with inspectable work: Avalanche randomness adds signal variance.","instruction":"比較同均值不同脈衝電荷變異的資料，定義額外雜訊。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Compare equal-mean signals with different charge variance and define excess noise. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"雪崩的隨機性會增加訊號變異；額外雜訊需在相同增益比較。","observationEn":"Avalanche randomness adds signal variance; Compare excess noise at matched gain.","failure":"若採用「把內部增益當成完全無雜訊放大」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating internal gain as noiseless amplification\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「倍增雜訊」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：雪崩的隨機性會增加訊號變異。","checkEn":"Submit the Multiplication noise diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Avalanche randomness adds signal variance.","knowledge":[{"id":"a079-v8-07-k1","title":"倍增雜訊／物理與模型","titleEn":"Multiplication noise / Physics and model","text":"機制：雪崩的隨機性會增加訊號變異。","textEn":"Mechanism: Avalanche randomness adds signal variance."},{"id":"a079-v8-07-k2","title":"倍增雜訊／驗證與限制","titleEn":"Multiplication noise / Verification and limits","text":"模型邊界：不可由目前成果直接推出「把內部增益當成完全無雜訊放大」。","textEn":"Model boundary: the current result does not establish the following claim: Treating internal gain as noiseless amplification."}],"quiz":{"question":"關於「倍增雜訊」，哪項推論有物理依據？","questionEn":"For Multiplication noise, which inference has a physical basis?","options":["雪崩的隨機性會增加訊號變異","把內部增益當成完全無雜訊放大","把全部暗電流一律乘以 M"],"optionsEn":["Avalanche randomness adds signal variance","Treating internal gain as noiseless amplification","Multiplying every dark-current component by M"],"answer":0,"explanation":"雪崩的隨機性會增加訊號變異；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Avalanche randomness adds signal variance. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-08","order":2,"sequence":8,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-07"],"title":"倍增雜訊：故障判讀與驗證","titleEn":"Multiplication noise: diagnose and verify","objective":"以新增對照檢查「把內部增益當成完全無雜訊放大」這項錯誤主張。","objectiveEn":"Test the faulty claim: Treating internal gain as noiseless amplification.","instruction":"接續前一步「倍增雜訊」成果，先指出錯誤主張「把內部增益當成完全無雜訊放大」漏掉哪個條件。新增診斷原理：額外雜訊需在相同增益比較。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Multiplication noise artifact. Identify the missing condition in the faulty claim \"Treating internal gain as noiseless amplification\". Introduce this diagnostic principle: Compare excess noise at matched gain. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"雪崩的隨機性會增加訊號變異；額外雜訊需在相同增益比較。","observationEn":"Avalanche randomness adds signal variance; Compare excess noise at matched gain.","failure":"若採用「把內部增益當成完全無雜訊放大」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Treating internal gain as noiseless amplification\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「倍增雜訊」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「額外雜訊需在相同增益比較」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Multiplication noise, its observable and one remaining uncertainty. Explain how \"Compare excess noise at matched gain\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-08-k1","title":"倍增雜訊／物理與模型","titleEn":"Multiplication noise / Physics and model","text":"診斷機制：額外雜訊需在相同增益比較。","textEn":"Diagnostic mechanism: Compare excess noise at matched gain."},{"id":"a079-v8-08-k2","title":"倍增雜訊／驗證與限制","titleEn":"Multiplication noise / Verification and limits","text":"可證偽性：「把內部增益當成完全無雜訊放大」與「雪崩的隨機性會增加訊號變異」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Treating internal gain as noiseless amplification\" is not equivalent to \"Avalanche randomness adds signal variance\"; the control must expose their difference."}],"quiz":{"question":"檢查「倍增雜訊」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Multiplication noise?","options":["把全部暗電流一律乘以 M","額外雜訊需在相同增益比較","把內部增益當成完全無雜訊放大"],"optionsEn":["Multiplying every dark-current component by M","Compare excess noise at matched gain","Treating internal gain as noiseless amplification"],"answer":1,"explanation":"額外雜訊需在相同增益比較；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Compare excess noise at matched gain. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-09","order":3,"sequence":9,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-08"],"title":"暗電流來源：建立模型","titleEn":"Dark-current sources: construct and analyze","objective":"用可檢查的成果說明「並非所有暗電流都乘上相同倍增因子」。","objectiveEn":"Demonstrate the following with inspectable work: Not all dark-current components share multiplication.","instruction":"分開表面漏電與經倍增區的體生成電流。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Separate surface leakage from multiplied bulk-generated current. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"並非所有暗電流都乘上相同倍增因子；暗電流需要和量測帶寬一起解釋。","observationEn":"Not all dark-current components share multiplication; Interpret dark current with measurement bandwidth.","failure":"若採用「把全部暗電流一律乘以 M」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Multiplying every dark-current component by M\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「暗電流來源」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：並非所有暗電流都乘上相同倍增因子。","checkEn":"Submit the Dark-current sources diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Not all dark-current components share multiplication.","knowledge":[{"id":"a079-v8-09-k1","title":"暗電流來源／物理與模型","titleEn":"Dark-current sources / Physics and model","text":"機制：並非所有暗電流都乘上相同倍增因子。","textEn":"Mechanism: Not all dark-current components share multiplication."},{"id":"a079-v8-09-k2","title":"暗電流來源／驗證與限制","titleEn":"Dark-current sources / Verification and limits","text":"模型邊界：不可由目前成果直接推出「把全部暗電流一律乘以 M」。","textEn":"Model boundary: the current result does not establish the following claim: Multiplying every dark-current component by M."}],"quiz":{"question":"關於「暗電流來源」，哪項推論有物理依據？","questionEn":"For Dark-current sources, which inference has a physical basis?","options":["把全部暗電流一律乘以 M","固定偏壓即可保證全年固定增益","並非所有暗電流都乘上相同倍增因子"],"optionsEn":["Multiplying every dark-current component by M","Assuming fixed bias guarantees fixed gain across temperatures","Not all dark-current components share multiplication"],"answer":2,"explanation":"並非所有暗電流都乘上相同倍增因子；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Not all dark-current components share multiplication. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-10","order":4,"sequence":10,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-09"],"title":"暗電流來源：故障判讀與驗證","titleEn":"Dark-current sources: diagnose and verify","objective":"以新增對照檢查「把全部暗電流一律乘以 M」這項錯誤主張。","objectiveEn":"Test the faulty claim: Multiplying every dark-current component by M.","instruction":"接續前一步「暗電流來源」成果，先指出錯誤主張「把全部暗電流一律乘以 M」漏掉哪個條件。新增診斷原理：暗電流需要和量測帶寬一起解釋。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Dark-current sources artifact. Identify the missing condition in the faulty claim \"Multiplying every dark-current component by M\". Introduce this diagnostic principle: Interpret dark current with measurement bandwidth. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"並非所有暗電流都乘上相同倍增因子；暗電流需要和量測帶寬一起解釋。","observationEn":"Not all dark-current components share multiplication; Interpret dark current with measurement bandwidth.","failure":"若採用「把全部暗電流一律乘以 M」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Multiplying every dark-current component by M\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「暗電流來源」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「暗電流需要和量測帶寬一起解釋」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Dark-current sources, its observable and one remaining uncertainty. Explain how \"Interpret dark current with measurement bandwidth\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-10-k1","title":"暗電流來源／物理與模型","titleEn":"Dark-current sources / Physics and model","text":"診斷機制：暗電流需要和量測帶寬一起解釋。","textEn":"Diagnostic mechanism: Interpret dark current with measurement bandwidth."},{"id":"a079-v8-10-k2","title":"暗電流來源／驗證與限制","titleEn":"Dark-current sources / Verification and limits","text":"可證偽性：「把全部暗電流一律乘以 M」與「並非所有暗電流都乘上相同倍增因子」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Multiplying every dark-current component by M\" is not equivalent to \"Not all dark-current components share multiplication\"; the control must expose their difference."}],"quiz":{"question":"檢查「暗電流來源」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Dark-current sources?","options":["暗電流需要和量測帶寬一起解釋","把全部暗電流一律乘以 M","固定偏壓即可保證全年固定增益"],"optionsEn":["Interpret dark current with measurement bandwidth","Multiplying every dark-current component by M","Assuming fixed bias guarantees fixed gain across temperatures"],"answer":0,"explanation":"暗電流需要和量測帶寬一起解釋；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Interpret dark current with measurement bandwidth. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-11","order":5,"sequence":11,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-10"],"title":"溫度補償：建立模型","titleEn":"Temperature compensation: construct and analyze","objective":"用可檢查的成果說明「溫度改變會移動增益與崩潰條件」。","objectiveEn":"Demonstrate the following with inspectable work: Temperature changes gain and breakdown conditions.","instruction":"畫兩溫度的增益偏壓曲線，找保持相同增益的偏壓差。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw gain-bias curves at two temperatures and find equal-gain bias differences. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"溫度改變會移動增益與崩潰條件；偏壓補償需避免溫度感測延遲。","observationEn":"Temperature changes gain and breakdown conditions; Bias compensation must consider thermal-sensor lag.","failure":"若採用「固定偏壓即可保證全年固定增益」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming fixed bias guarantees fixed gain across temperatures\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「溫度補償」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：溫度改變會移動增益與崩潰條件。","checkEn":"Submit the Temperature compensation diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Temperature changes gain and breakdown conditions.","knowledge":[{"id":"a079-v8-11-k1","title":"溫度補償／物理與模型","titleEn":"Temperature compensation / Physics and model","text":"機制：溫度改變會移動增益與崩潰條件。","textEn":"Mechanism: Temperature changes gain and breakdown conditions."},{"id":"a079-v8-11-k2","title":"溫度補償／驗證與限制","titleEn":"Temperature compensation / Verification and limits","text":"模型邊界：不可由目前成果直接推出「固定偏壓即可保證全年固定增益」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming fixed bias guarantees fixed gain across temperatures."}],"quiz":{"question":"關於「溫度補償」，哪項推論有物理依據？","questionEn":"For Temperature compensation, which inference has a physical basis?","options":["只降低外部電阻就無限制提升速度","溫度改變會移動增益與崩潰條件","固定偏壓即可保證全年固定增益"],"optionsEn":["Assuming resistance reduction provides unlimited speed","Temperature changes gain and breakdown conditions","Assuming fixed bias guarantees fixed gain across temperatures"],"answer":1,"explanation":"溫度改變會移動增益與崩潰條件；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Temperature changes gain and breakdown conditions. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-12","order":6,"sequence":12,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-11"],"title":"溫度補償：故障判讀與驗證","titleEn":"Temperature compensation: diagnose and verify","objective":"以新增對照檢查「固定偏壓即可保證全年固定增益」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming fixed bias guarantees fixed gain across temperatures.","instruction":"接續前一步「溫度補償」成果，先指出錯誤主張「固定偏壓即可保證全年固定增益」漏掉哪個條件。新增診斷原理：偏壓補償需避免溫度感測延遲。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Temperature compensation artifact. Identify the missing condition in the faulty claim \"Assuming fixed bias guarantees fixed gain across temperatures\". Introduce this diagnostic principle: Bias compensation must consider thermal-sensor lag. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"溫度改變會移動增益與崩潰條件；偏壓補償需避免溫度感測延遲。","observationEn":"Temperature changes gain and breakdown conditions; Bias compensation must consider thermal-sensor lag.","failure":"若採用「固定偏壓即可保證全年固定增益」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming fixed bias guarantees fixed gain across temperatures\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「溫度補償」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「偏壓補償需避免溫度感測延遲」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Temperature compensation, its observable and one remaining uncertainty. Explain how \"Bias compensation must consider thermal-sensor lag\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-12-k1","title":"溫度補償／物理與模型","titleEn":"Temperature compensation / Physics and model","text":"診斷機制：偏壓補償需避免溫度感測延遲。","textEn":"Diagnostic mechanism: Bias compensation must consider thermal-sensor lag."},{"id":"a079-v8-12-k2","title":"溫度補償／驗證與限制","titleEn":"Temperature compensation / Verification and limits","text":"可證偽性：「固定偏壓即可保證全年固定增益」與「溫度改變會移動增益與崩潰條件」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming fixed bias guarantees fixed gain across temperatures\" is not equivalent to \"Temperature changes gain and breakdown conditions\"; the control must expose their difference."}],"quiz":{"question":"檢查「溫度補償」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Temperature compensation?","options":["固定偏壓即可保證全年固定增益","只降低外部電阻就無限制提升速度","偏壓補償需避免溫度感測延遲"],"optionsEn":["Assuming fixed bias guarantees fixed gain across temperatures","Assuming resistance reduction provides unlimited speed","Bias compensation must consider thermal-sensor lag"],"answer":2,"explanation":"偏壓補償需避免溫度感測延遲；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Bias compensation must consider thermal-sensor lag. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a079-stage03","order":3,"title":"頻寬限制 → 面積與電容","titleEn":"Bandwidth limits to Area and capacitance","description":"把「頻寬限制」「光譜響應」「面積與電容」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Bandwidth limits, Spectral response, Area and capacitance.","steps":[{"id":"a079-v8-13","order":1,"sequence":13,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-12"],"title":"頻寬限制：建立模型","titleEn":"Bandwidth limits: construct and analyze","objective":"用可檢查的成果說明「最慢動態環節會限制響應」。","objectiveEn":"Demonstrate the following with inspectable work: The slowest dynamic process limits response.","instruction":"並列 RC 時間、載子渡越與雪崩建立時間的時間常數。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Compare RC, carrier transit and avalanche buildup time constants. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"最慢動態環節會限制響應；增益建立時間造成增益頻寬取捨。","observationEn":"The slowest dynamic process limits response; Avalanche buildup creates gain-bandwidth tradeoffs.","failure":"若採用「只降低外部電阻就無限制提升速度」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming resistance reduction provides unlimited speed\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「頻寬限制」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：最慢動態環節會限制響應。","checkEn":"Submit the Bandwidth limits diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: The slowest dynamic process limits response.","knowledge":[{"id":"a079-v8-13-k1","title":"頻寬限制／物理與模型","titleEn":"Bandwidth limits / Physics and model","text":"機制：最慢動態環節會限制響應。","textEn":"Mechanism: The slowest dynamic process limits response."},{"id":"a079-v8-13-k2","title":"頻寬限制／驗證與限制","titleEn":"Bandwidth limits / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只降低外部電阻就無限制提升速度」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming resistance reduction provides unlimited speed."}],"quiz":{"question":"關於「頻寬限制」，哪項推論有物理依據？","questionEn":"For Bandwidth limits, which inference has a physical basis?","options":["最慢動態環節會限制響應","只降低外部電阻就無限制提升速度","用單一波長響應代表全光譜"],"optionsEn":["The slowest dynamic process limits response","Assuming resistance reduction provides unlimited speed","Using one wavelength for the entire spectrum"],"answer":0,"explanation":"最慢動態環節會限制響應；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"The slowest dynamic process limits response. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-14","order":2,"sequence":14,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-13"],"title":"頻寬限制：故障判讀與驗證","titleEn":"Bandwidth limits: diagnose and verify","objective":"以新增對照檢查「只降低外部電阻就無限制提升速度」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming resistance reduction provides unlimited speed.","instruction":"接續前一步「頻寬限制」成果，先指出錯誤主張「只降低外部電阻就無限制提升速度」漏掉哪個條件。新增診斷原理：增益建立時間造成增益頻寬取捨。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Bandwidth limits artifact. Identify the missing condition in the faulty claim \"Assuming resistance reduction provides unlimited speed\". Introduce this diagnostic principle: Avalanche buildup creates gain-bandwidth tradeoffs. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"最慢動態環節會限制響應；增益建立時間造成增益頻寬取捨。","observationEn":"The slowest dynamic process limits response; Avalanche buildup creates gain-bandwidth tradeoffs.","failure":"若採用「只降低外部電阻就無限制提升速度」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming resistance reduction provides unlimited speed\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「頻寬限制」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「增益建立時間造成增益頻寬取捨」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Bandwidth limits, its observable and one remaining uncertainty. Explain how \"Avalanche buildup creates gain-bandwidth tradeoffs\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-14-k1","title":"頻寬限制／物理與模型","titleEn":"Bandwidth limits / Physics and model","text":"診斷機制：增益建立時間造成增益頻寬取捨。","textEn":"Diagnostic mechanism: Avalanche buildup creates gain-bandwidth tradeoffs."},{"id":"a079-v8-14-k2","title":"頻寬限制／驗證與限制","titleEn":"Bandwidth limits / Verification and limits","text":"可證偽性：「只降低外部電阻就無限制提升速度」與「最慢動態環節會限制響應」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming resistance reduction provides unlimited speed\" is not equivalent to \"The slowest dynamic process limits response\"; the control must expose their difference."}],"quiz":{"question":"檢查「頻寬限制」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Bandwidth limits?","options":["用單一波長響應代表全光譜","增益建立時間造成增益頻寬取捨","只降低外部電阻就無限制提升速度"],"optionsEn":["Using one wavelength for the entire spectrum","Avalanche buildup creates gain-bandwidth tradeoffs","Assuming resistance reduction provides unlimited speed"],"answer":1,"explanation":"增益建立時間造成增益頻寬取捨；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Avalanche buildup creates gain-bandwidth tradeoffs. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-15","order":3,"sequence":15,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-14"],"title":"光譜響應：建立模型","titleEn":"Spectral response: construct and analyze","objective":"用可檢查的成果說明「有效增益與收集效率可能有光譜依賴」。","objectiveEn":"Demonstrate the following with inspectable work: Effective gain and collection can depend on wavelength.","instruction":"將不同波長吸收深度與倍增區重疊比較。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Compare wavelength-dependent absorption depth with multiplication-region overlap. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"有效增益與收集效率可能有光譜依賴；表面反射會改變有效入射光通量。","observationEn":"Effective gain and collection can depend on wavelength; Reflection changes effective incident flux.","failure":"若採用「用單一波長響應代表全光譜」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Using one wavelength for the entire spectrum\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「光譜響應」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：有效增益與收集效率可能有光譜依賴。","checkEn":"Submit the Spectral response diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Effective gain and collection can depend on wavelength.","knowledge":[{"id":"a079-v8-15-k1","title":"光譜響應／物理與模型","titleEn":"Spectral response / Physics and model","text":"機制：有效增益與收集效率可能有光譜依賴。","textEn":"Mechanism: Effective gain and collection can depend on wavelength."},{"id":"a079-v8-15-k2","title":"光譜響應／驗證與限制","titleEn":"Spectral response / Verification and limits","text":"模型邊界：不可由目前成果直接推出「用單一波長響應代表全光譜」。","textEn":"Model boundary: the current result does not establish the following claim: Using one wavelength for the entire spectrum."}],"quiz":{"question":"關於「光譜響應」，哪項推論有物理依據？","questionEn":"For Spectral response, which inference has a physical basis?","options":["用單一波長響應代表全光譜","大面積在靈敏度和速度上都必然最佳","有效增益與收集效率可能有光譜依賴"],"optionsEn":["Using one wavelength for the entire spectrum","Assuming largest area is always best for sensitivity and speed","Effective gain and collection can depend on wavelength"],"answer":2,"explanation":"有效增益與收集效率可能有光譜依賴；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Effective gain and collection can depend on wavelength. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-16","order":4,"sequence":16,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-15"],"title":"光譜響應：故障判讀與驗證","titleEn":"Spectral response: diagnose and verify","objective":"以新增對照檢查「用單一波長響應代表全光譜」這項錯誤主張。","objectiveEn":"Test the faulty claim: Using one wavelength for the entire spectrum.","instruction":"接續前一步「光譜響應」成果，先指出錯誤主張「用單一波長響應代表全光譜」漏掉哪個條件。新增診斷原理：表面反射會改變有效入射光通量。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Spectral response artifact. Identify the missing condition in the faulty claim \"Using one wavelength for the entire spectrum\". Introduce this diagnostic principle: Reflection changes effective incident flux. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"有效增益與收集效率可能有光譜依賴；表面反射會改變有效入射光通量。","observationEn":"Effective gain and collection can depend on wavelength; Reflection changes effective incident flux.","failure":"若採用「用單一波長響應代表全光譜」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Using one wavelength for the entire spectrum\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「光譜響應」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「表面反射會改變有效入射光通量」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Spectral response, its observable and one remaining uncertainty. Explain how \"Reflection changes effective incident flux\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-16-k1","title":"光譜響應／物理與模型","titleEn":"Spectral response / Physics and model","text":"診斷機制：表面反射會改變有效入射光通量。","textEn":"Diagnostic mechanism: Reflection changes effective incident flux."},{"id":"a079-v8-16-k2","title":"光譜響應／驗證與限制","titleEn":"Spectral response / Verification and limits","text":"可證偽性：「用單一波長響應代表全光譜」與「有效增益與收集效率可能有光譜依賴」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Using one wavelength for the entire spectrum\" is not equivalent to \"Effective gain and collection can depend on wavelength\"; the control must expose their difference."}],"quiz":{"question":"檢查「光譜響應」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Spectral response?","options":["表面反射會改變有效入射光通量","用單一波長響應代表全光譜","大面積在靈敏度和速度上都必然最佳"],"optionsEn":["Reflection changes effective incident flux","Using one wavelength for the entire spectrum","Assuming largest area is always best for sensitivity and speed"],"answer":0,"explanation":"表面反射會改變有效入射光通量；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Reflection changes effective incident flux. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-17","order":5,"sequence":17,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-16"],"title":"面積與電容：建立模型","titleEn":"Area and capacitance: construct and analyze","objective":"用可檢查的成果說明「增大面積會同時改變光學與電路負載」。","objectiveEn":"Demonstrate the following with inspectable work: Larger area changes both optical collection and circuit loading.","instruction":"對兩個假設接面面積比較收光、電容與暗電流。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Compare collection, capacitance and dark current for two areas. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"增大面積會同時改變光學與電路負載；大面積也增加缺陷採樣機會。","observationEn":"Larger area changes both optical collection and circuit loading; Large area also samples more defects.","failure":"若採用「大面積在靈敏度和速度上都必然最佳」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming largest area is always best for sensitivity and speed\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「面積與電容」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：增大面積會同時改變光學與電路負載。","checkEn":"Submit the Area and capacitance diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Larger area changes both optical collection and circuit loading.","knowledge":[{"id":"a079-v8-17-k1","title":"面積與電容／物理與模型","titleEn":"Area and capacitance / Physics and model","text":"機制：增大面積會同時改變光學與電路負載。","textEn":"Mechanism: Larger area changes both optical collection and circuit loading."},{"id":"a079-v8-17-k2","title":"面積與電容／驗證與限制","titleEn":"Area and capacitance / Verification and limits","text":"模型邊界：不可由目前成果直接推出「大面積在靈敏度和速度上都必然最佳」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming largest area is always best for sensitivity and speed."}],"quiz":{"question":"關於「面積與電容」，哪項推論有物理依據？","questionEn":"For Area and capacitance, which inference has a physical basis?","options":["只看裸晶參數推定模組表現","增大面積會同時改變光學與電路負載","大面積在靈敏度和速度上都必然最佳"],"optionsEn":["Predicting module performance from bare-die parameters alone","Larger area changes both optical collection and circuit loading","Assuming largest area is always best for sensitivity and speed"],"answer":1,"explanation":"增大面積會同時改變光學與電路負載；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Larger area changes both optical collection and circuit loading. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-18","order":6,"sequence":18,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-17"],"title":"面積與電容：故障判讀與驗證","titleEn":"Area and capacitance: diagnose and verify","objective":"以新增對照檢查「大面積在靈敏度和速度上都必然最佳」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming largest area is always best for sensitivity and speed.","instruction":"接續前一步「面積與電容」成果，先指出錯誤主張「大面積在靈敏度和速度上都必然最佳」漏掉哪個條件。新增診斷原理：大面積也增加缺陷採樣機會。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Area and capacitance artifact. Identify the missing condition in the faulty claim \"Assuming largest area is always best for sensitivity and speed\". Introduce this diagnostic principle: Large area also samples more defects. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"增大面積會同時改變光學與電路負載；大面積也增加缺陷採樣機會。","observationEn":"Larger area changes both optical collection and circuit loading; Large area also samples more defects.","failure":"若採用「大面積在靈敏度和速度上都必然最佳」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming largest area is always best for sensitivity and speed\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「面積與電容」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「大面積也增加缺陷採樣機會」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Area and capacitance, its observable and one remaining uncertainty. Explain how \"Large area also samples more defects\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-18-k1","title":"面積與電容／物理與模型","titleEn":"Area and capacitance / Physics and model","text":"診斷機制：大面積也增加缺陷採樣機會。","textEn":"Diagnostic mechanism: Large area also samples more defects."},{"id":"a079-v8-18-k2","title":"面積與電容／驗證與限制","titleEn":"Area and capacitance / Verification and limits","text":"可證偽性：「大面積在靈敏度和速度上都必然最佳」與「增大面積會同時改變光學與電路負載」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming largest area is always best for sensitivity and speed\" is not equivalent to \"Larger area changes both optical collection and circuit loading\"; the control must expose their difference."}],"quiz":{"question":"檢查「面積與電容」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Area and capacitance?","options":["大面積在靈敏度和速度上都必然最佳","只看裸晶參數推定模組表現","大面積也增加缺陷採樣機會"],"optionsEn":["Assuming largest area is always best for sensitivity and speed","Predicting module performance from bare-die parameters alone","Large area also samples more defects"],"answer":2,"explanation":"大面積也增加缺陷採樣機會；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Large area also samples more defects. The competing claim omits a necessary condition or mechanism."}}]},{"id":"a079-stage04","order":4,"title":"接觸與封裝 → 偵測系統","titleEn":"Contacts and package to Detection system","description":"把「接觸與封裝」「增益校正」「偵測系統」各拆成模型與診斷兩項工作，保留可檢查成果。","descriptionEn":"Develop model and diagnostic deliverables for Contacts and package, Gain calibration, Detection system.","steps":[{"id":"a079-v8-19","order":1,"sequence":19,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-18"],"title":"接觸與封裝：建立模型","titleEn":"Contacts and package: construct and analyze","objective":"用可檢查的成果說明「封裝可限制晶片原有響應」。","objectiveEn":"Demonstrate the following with inspectable work: Packaging can limit intrinsic chip response.","instruction":"畫反射窗口、鍵合線與放大器輸入，列出寄生和遮光。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Draw window, bonds and amplifier input with parasitics and shading. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"封裝可限制晶片原有響應；接收窗污染可能造成靈敏度下降。","observationEn":"Packaging can limit intrinsic chip response; Window contamination can reduce sensitivity.","failure":"若採用「只看裸晶參數推定模組表現」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Predicting module performance from bare-die parameters alone\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「接觸與封裝」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：封裝可限制晶片原有響應。","checkEn":"Submit the Contacts and package diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Packaging can limit intrinsic chip response.","knowledge":[{"id":"a079-v8-19-k1","title":"接觸與封裝／物理與模型","titleEn":"Contacts and package / Physics and model","text":"機制：封裝可限制晶片原有響應。","textEn":"Mechanism: Packaging can limit intrinsic chip response."},{"id":"a079-v8-19-k2","title":"接觸與封裝／驗證與限制","titleEn":"Contacts and package / Verification and limits","text":"模型邊界：不可由目前成果直接推出「只看裸晶參數推定模組表現」。","textEn":"Model boundary: the current result does not establish the following claim: Predicting module performance from bare-die parameters alone."}],"quiz":{"question":"關於「接觸與封裝」，哪項推論有物理依據？","questionEn":"For Contacts and package, which inference has a physical basis?","options":["封裝可限制晶片原有響應","只看裸晶參數推定模組表現","不同光強下的電流比直接當 M"],"optionsEn":["Packaging can limit intrinsic chip response","Predicting module performance from bare-die parameters alone","Calling a ratio at different illumination the gain"],"answer":0,"explanation":"封裝可限制晶片原有響應；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Packaging can limit intrinsic chip response. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-20","order":2,"sequence":20,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-19"],"title":"接觸與封裝：故障判讀與驗證","titleEn":"Contacts and package: diagnose and verify","objective":"以新增對照檢查「只看裸晶參數推定模組表現」這項錯誤主張。","objectiveEn":"Test the faulty claim: Predicting module performance from bare-die parameters alone.","instruction":"接續前一步「接觸與封裝」成果，先指出錯誤主張「只看裸晶參數推定模組表現」漏掉哪個條件。新增診斷原理：接收窗污染可能造成靈敏度下降。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Contacts and package artifact. Identify the missing condition in the faulty claim \"Predicting module performance from bare-die parameters alone\". Introduce this diagnostic principle: Window contamination can reduce sensitivity. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"封裝可限制晶片原有響應；接收窗污染可能造成靈敏度下降。","observationEn":"Packaging can limit intrinsic chip response; Window contamination can reduce sensitivity.","failure":"若採用「只看裸晶參數推定模組表現」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Predicting module performance from bare-die parameters alone\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「接觸與封裝」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「接收窗污染可能造成靈敏度下降」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Contacts and package, its observable and one remaining uncertainty. Explain how \"Window contamination can reduce sensitivity\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-20-k1","title":"接觸與封裝／物理與模型","titleEn":"Contacts and package / Physics and model","text":"診斷機制：接收窗污染可能造成靈敏度下降。","textEn":"Diagnostic mechanism: Window contamination can reduce sensitivity."},{"id":"a079-v8-20-k2","title":"接觸與封裝／驗證與限制","titleEn":"Contacts and package / Verification and limits","text":"可證偽性：「只看裸晶參數推定模組表現」與「封裝可限制晶片原有響應」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Predicting module performance from bare-die parameters alone\" is not equivalent to \"Packaging can limit intrinsic chip response\"; the control must expose their difference."}],"quiz":{"question":"檢查「接觸與封裝」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Contacts and package?","options":["不同光強下的電流比直接當 M","接收窗污染可能造成靈敏度下降","只看裸晶參數推定模組表現"],"optionsEn":["Calling a ratio at different illumination the gain","Window contamination can reduce sensitivity","Predicting module performance from bare-die parameters alone"],"answer":1,"explanation":"接收窗污染可能造成靈敏度下降；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Window contamination can reduce sensitivity. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-21","order":3,"sequence":21,"estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-20"],"title":"增益校正：建立模型","titleEn":"Gain calibration: construct and analyze","objective":"用可檢查的成果說明「光源漂移會混入增益估計」。","objectiveEn":"Demonstrate the following with inspectable work: Source drift contaminates gain estimates.","instruction":"用同光通量比較低倍增參考與工作偏壓電流並扣暗電流。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。\n\n具體算例（全部數值為教學假設）：假設相同光通量下，已扣暗電流的單位增益參考光電流為 10 nA，工作偏壓下為 200 nA，雪崩增益 M=200/10=20。若未扣暗電流便用總電流相除，可能偏差。此例假定參考確為 M=1，且不提供過剩雜訊或擊穿電壓資訊。","instructionEn":"Compare low-gain and operating currents at equal flux with dark subtraction. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.\n\nWorked example (all values are hypothetical teaching inputs): Assume equal photon flux and dark-subtracted photocurrents of 10 nA at a unit-gain reference and 200 nA at operating bias. Avalanche gain M=200/10=20. Dividing total currents without dark subtraction can bias gain. The reference is assumed to have M=1; the example does not determine excess noise or breakdown voltage.","observation":"光源漂移會混入增益估計；低偏壓參考仍需確認收集效率。","observationEn":"Source drift contaminates gain estimates; Low-bias references still need collection checks.","failure":"若採用「不同光強下的電流比直接當 M」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Calling a ratio at different illumination the gain\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「增益校正」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：光源漂移會混入增益估計。\n算例驗收：驗算 M=20，寫出兩個必要條件：等光通量與暗電流扣除，另註明單位增益參考假設。","checkEn":"Submit the Gain calibration diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Source drift contaminates gain estimates.\nWorked-example acceptance: Verify M=20 and record equal flux, dark subtraction and the assumed unit-gain reference.","knowledge":[{"id":"a079-v8-21-k1","title":"增益校正／物理與模型","titleEn":"Gain calibration / Physics and model","text":"機制：光源漂移會混入增益估計。","textEn":"Mechanism: Source drift contaminates gain estimates."},{"id":"a079-v8-21-k2","title":"增益校正／驗證與限制","titleEn":"Gain calibration / Verification and limits","text":"模型邊界：不可由目前成果直接推出「不同光強下的電流比直接當 M」。\n假設數值與推算：假設相同光通量下，已扣暗電流的單位增益參考光電流為 10 nA，工作偏壓下為 200 nA，雪崩增益 M=200/10=20。若未扣暗電流便用總電流相除，可能偏差。此例假定參考確為 M=1，且不提供過剩雜訊或擊穿電壓資訊。","textEn":"Model boundary: the current result does not establish the following claim: Calling a ratio at different illumination the gain.\nHypothetical inputs and calculation: Assume equal photon flux and dark-subtracted photocurrents of 10 nA at a unit-gain reference and 200 nA at operating bias. Avalanche gain M=200/10=20. Dividing total currents without dark subtraction can bias gain. The reference is assumed to have M=1; the example does not determine excess noise or breakdown voltage."}],"quiz":{"question":"關於「增益校正」，哪項推論有物理依據？","questionEn":"For Gain calibration, which inference has a physical basis?","options":["不同光強下的電流比直接當 M","增益越高訊雜比永遠越好","光源漂移會混入增益估計"],"optionsEn":["Calling a ratio at different illumination the gain","Assuming SNR always increases with gain","Source drift contaminates gain estimates"],"answer":2,"explanation":"光源漂移會混入增益估計；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Source drift contaminates gain estimates. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-22","order":4,"sequence":22,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-21"],"title":"增益校正：故障判讀與驗證","titleEn":"Gain calibration: diagnose and verify","objective":"以新增對照檢查「不同光強下的電流比直接當 M」這項錯誤主張。","objectiveEn":"Test the faulty claim: Calling a ratio at different illumination the gain.","instruction":"接續前一步「增益校正」成果，先指出錯誤主張「不同光強下的電流比直接當 M」漏掉哪個條件。新增診斷原理：低偏壓參考仍需確認收集效率。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Gain calibration artifact. Identify the missing condition in the faulty claim \"Calling a ratio at different illumination the gain\". Introduce this diagnostic principle: Low-bias references still need collection checks. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"光源漂移會混入增益估計；低偏壓參考仍需確認收集效率。","observationEn":"Source drift contaminates gain estimates; Low-bias references still need collection checks.","failure":"若採用「不同光強下的電流比直接當 M」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Calling a ratio at different illumination the gain\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「增益校正」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「低偏壓參考仍需確認收集效率」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Gain calibration, its observable and one remaining uncertainty. Explain how \"Low-bias references still need collection checks\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-22-k1","title":"增益校正／物理與模型","titleEn":"Gain calibration / Physics and model","text":"診斷機制：低偏壓參考仍需確認收集效率。","textEn":"Diagnostic mechanism: Low-bias references still need collection checks."},{"id":"a079-v8-22-k2","title":"增益校正／驗證與限制","titleEn":"Gain calibration / Verification and limits","text":"可證偽性：「不同光強下的電流比直接當 M」與「光源漂移會混入增益估計」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Calling a ratio at different illumination the gain\" is not equivalent to \"Source drift contaminates gain estimates\"; the control must expose their difference."}],"quiz":{"question":"檢查「增益校正」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Gain calibration?","options":["低偏壓參考仍需確認收集效率","不同光強下的電流比直接當 M","增益越高訊雜比永遠越好"],"optionsEn":["Low-bias references still need collection checks","Calling a ratio at different illumination the gain","Assuming SNR always increases with gain"],"answer":0,"explanation":"低偏壓參考仍需確認收集效率；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Low-bias references still need collection checks. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-23","order":5,"sequence":23,"estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-22"],"title":"偵測系統：建立模型","titleEn":"Detection system: construct and analyze","objective":"用可檢查的成果說明「最佳增益取決於整個雜訊預算」。","objectiveEn":"Demonstrate the following with inspectable work: Optimal gain depends on the complete noise budget.","instruction":"合併光子雜訊、倍增雜訊與讀出雜訊，比較兩個假設增益。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。","instructionEn":"Combine photon, multiplication and readout noise for two gains. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.","observation":"最佳增益取決於整個雜訊預算；放大器輸入電容會影響最佳配置。","observationEn":"Optimal gain depends on the complete noise budget; Amplifier input capacitance affects optimal configuration.","failure":"若採用「增益越高訊雜比永遠越好」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming SNR always increases with gain\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"提交「偵測系統」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和輸出，並說明：最佳增益取決於整個雜訊預算。","checkEn":"Submit the Detection system diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: Optimal gain depends on the complete noise budget.","knowledge":[{"id":"a079-v8-23-k1","title":"偵測系統／物理與模型","titleEn":"Detection system / Physics and model","text":"機制：最佳增益取決於整個雜訊預算。","textEn":"Mechanism: Optimal gain depends on the complete noise budget."},{"id":"a079-v8-23-k2","title":"偵測系統／驗證與限制","titleEn":"Detection system / Verification and limits","text":"模型邊界：不可由目前成果直接推出「增益越高訊雜比永遠越好」。","textEn":"Model boundary: the current result does not establish the following claim: Assuming SNR always increases with gain."}],"quiz":{"question":"關於「偵測系統」，哪項推論有物理依據？","questionEn":"For Detection system, which inference has a physical basis?","options":["把整個元件都畫成相同高場","最佳增益取決於整個雜訊預算","增益越高訊雜比永遠越好"],"optionsEn":["Drawing uniform high field throughout the device","Optimal gain depends on the complete noise budget","Assuming SNR always increases with gain"],"answer":1,"explanation":"最佳增益取決於整個雜訊預算；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Optimal gain depends on the complete noise budget. The competing claim omits a necessary condition or mechanism."}},{"id":"a079-v8-24","order":6,"sequence":24,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v8-c-apd","v8-c-sipm"],"prerequisiteIds":["a079-v8-23"],"title":"偵測系統：故障判讀與驗證","titleEn":"Detection system: diagnose and verify","objective":"以新增對照檢查「增益越高訊雜比永遠越好」這項錯誤主張。","objectiveEn":"Test the faulty claim: Assuming SNR always increases with gain.","instruction":"接續前一步「偵測系統」成果，先指出錯誤主張「增益越高訊雜比永遠越好」漏掉哪個條件。新增診斷原理：放大器輸入電容會影響最佳配置。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。","instructionEn":"Continue the preceding Detection system artifact. Identify the missing condition in the faulty claim \"Assuming SNR always increases with gain\". Introduce this diagnostic principle: Amplifier input capacitance affects optimal configuration. Design normal/fault controls; specify a distinguishing observable, sampling location or time; state what remains undecided without evidence. Do not fabricate measurements.","observation":"最佳增益取決於整個雜訊預算；放大器輸入電容會影響最佳配置。","observationEn":"Optimal gain depends on the complete noise budget; Amplifier input capacitance affects optimal configuration.","failure":"若採用「增益越高訊雜比永遠越好」，先回到前一步模型，檢查假設、量測條件及本步的診斷因素。","failureEn":"If using the claim \"Assuming SNR always increases with gain\", return to the model and check assumptions, measurement conditions and the diagnostic factor.","check":"交出「偵測系統」的正常／異常比較、可觀察量與一項仍未確定事項；必須解釋「放大器輸入電容會影響最佳配置」如何改變前一步的判讀。","checkEn":"Submit a normal/fault comparison for Detection system, its observable and one remaining uncertainty. Explain how \"Amplifier input capacitance affects optimal configuration\" changes interpretation of the preceding artifact.","knowledge":[{"id":"a079-v8-24-k1","title":"偵測系統／物理與模型","titleEn":"Detection system / Physics and model","text":"診斷機制：放大器輸入電容會影響最佳配置。","textEn":"Diagnostic mechanism: Amplifier input capacitance affects optimal configuration."},{"id":"a079-v8-24-k2","title":"偵測系統／驗證與限制","titleEn":"Detection system / Verification and limits","text":"可證偽性：「增益越高訊雜比永遠越好」與「最佳增益取決於整個雜訊預算」不可混為同一推論；對照需能觀察兩者的差別。","textEn":"Falsifiability: \"Assuming SNR always increases with gain\" is not equivalent to \"Optimal gain depends on the complete noise budget\"; the control must expose their difference."}],"quiz":{"question":"檢查「偵測系統」時，哪個新增因素應納入？","questionEn":"Which additional factor belongs in a check of Detection system?","options":["增益越高訊雜比永遠越好","把整個元件都畫成相同高場","放大器輸入電容會影響最佳配置"],"optionsEn":["Assuming SNR always increases with gain","Drawing uniform high field throughout the device","Amplifier input capacitance affects optimal configuration"],"answer":2,"explanation":"放大器輸入電容會影響最佳配置；錯誤主張的問題是未保留必要條件或機制。","explanationEn":"Amplifier input capacitance affects optimal configuration. The competing claim omits a necessary condition or mechanism."}}]}],"subcategory":"sensors","subcategoryTitle":"影像與光子感測","subcategoryTitleEn":"Image and photon sensors"}};
